INSERT INTO fitment_pages (vehicle_id, category_id, title, meta_desc, intro_md, gotchas_md, faq, verdict_md, status, verified_at)
SELECT v.id, c.id, $t$Best Floor Mats & Liners for 2015–2020 Ford F-150 (SuperCrew)$t$, $m$Laser-fit floor liners and all-weather mats checked against the 2015–2020 Ford F-150 by cab, seating and storage layout — plus the layout gotchas that cause returns.$m$, $i$Every set below is listed for the 2015–2020 Ford F-150, not a 'universal trim-to-fit' mat. Liners fail for three reasons: wrong generation, wrong seating layout (bench vs buckets, 2nd-row captain's chairs vs bench) and wrong under-seat storage. Check those three against the notes on each pick and the fit is a non-issue.$i$, $g$- **13th-gen only** (P552). 2021+ floors differ; don't cross-shop listings that stop at 2020 with 2021+.
- **Fold-flat rear storage**: some SuperCrews have the rear under-seat fold-flat load floor — several liners say 'not for fold-flat storage'. Look under the rear seat before ordering.
- **Front bench vs buckets** changes the front hump piece — check your console.
- **Retention hooks**: factory driver-side hooks must line up — a mat without hook holes will slide under the pedals. All picks here are cut for the factory posts.
- **Stacking**: never lay a liner on top of the carpet mat. Remove the factory mat first.$g$, $f$[{"q": "Do 2021+ F-150 liners fit a 2019?", "a": "No — the 14th gen changed the floor pan and console."}, {"q": "TPE liners or rubber mats?", "a": "TPE liners (raised edges, laser-measured) hold water and snow and look OEM; rubber mats are cheaper, heavier and grip better but cover less of the footwell."}, {"q": "Do I need the 2nd-row piece?", "a": "Yes if anyone rides back there — mud collects on the rear floor first. Most sets here include 1st + 2nd row; 3rd-row and cargo liners are usually separate."}]$f$::jsonb, $v$**Budget:** a molded rubber set listed for your layout. **Best overall:** TPE laser-fit liners, 1st + 2nd row. **Premium:** maximum-coverage liners that run up the door sills.$v$, 'draft', CURRENT_DATE
FROM vehicles v JOIN makes m ON m.id=v.make_id JOIN categories c ON c.slug='floor-mats'
WHERE m.slug='ford' AND v.model_slug='f-150' AND v.gen_slug='2015-2020'
ON CONFLICT (vehicle_id, category_id) DO UPDATE SET title=EXCLUDED.title, meta_desc=EXCLUDED.meta_desc, intro_md=EXCLUDED.intro_md,
  gotchas_md=EXCLUDED.gotchas_md, faq=EXCLUDED.faq, verdict_md=EXCLUDED.verdict_md, verified_at=EXCLUDED.verified_at, updated_at=now();

